#!/usr/bin/env python3
"""Validate actual generated bytes, mesh counts and texture inventory; no empty placeholder assets."""
import json
from pathlib import Path
import struct
import sys

def check(condition, label):
    if not condition:
        raise AssertionError(label)

def size(path, minimum=64):
    check(path.is_file(), "missing: " + str(path))
    check(path.stat().st_size > minimum, "empty or too small: " + str(path))
    return path.stat().st_size

def main(root):
    root = Path(root)
    manifest = json.loads((root / "manifest.json").read_text(encoding="utf-8"))
    names = ["cyan", "amber", "violet", "emerald"]
    pieces = ["torso", "head", "left_arm", "right_arm", "left_leg", "right_leg", "rifle"]
    check(manifest["palette"] == names, "palette mismatch")
    check(manifest["format"]["components"] == pieces, "component manifest mismatch")
    check(manifest["format"]["asset_ids_published"] is False, "cannot claim Studio upload")
    check(manifest["format"]["skinned"] is False, "rigid asset must not claim skin weights")
    files = []
    for piece in pieces:
        path = root / "parts" / ("vanguard_" + piece + ".fbx")
        size(path, 1024)
        header = path.read_bytes()[:23]
        check(header.startswith(b"Kaydara FBX Binary"), "incorrect FBX header: " + str(path))
        files.append(path)
    for name in names:
        for lod in ("LOD0", "LOD1"):
            p = root / "meshes" / ("vanguard_" + name + "_" + lod + ".glb")
            size(p, 2048)
            with p.open("rb") as stream:
                magic, version, total_bytes = struct.unpack("<4sII", stream.read(12))
            check(magic == b"glTF" and version == 2, "not glTF 2: " + str(p))
            check(total_bytes == p.stat().st_size, "GLB reported size mismatch: " + str(p))
            files.append(p)
        check(manifest["polygons_by_color_LOD0"].get(name, 0) > 250, "model not detailed enough: " + name)
    for name in ["armor", "carbon", "gunmetal", "visor"] + ["accent_" + n for n in names]:
        for kind in ("ColorMap", "NormalMap", "RoughnessMap", "MetalnessMap"):
            path = root / "textures" / (name + "_" + kind + ".png")
            size(path, 1024)
            with path.open("rb") as stream:
                header = stream.read(24)
            check(header[:8] == b"\x89PNG\r\n\x1a\n", "bad PNG: " + str(path))
            check(struct.unpack(">II", header[16:24]) == (512, 512), "wrong PBR map dimensions: " + str(path))
            files.append(path)
    size(root / "vanguard_source.blend", 4096)
    preview = root / "preview" / "vanguard_contact_sheet.png"
    size(preview, 4096)
    files.extend([preview, root / "vanguard_source.blend"])
    output = (
        "- **7** real FBX mesh parts (R6), **8** GLB 2.0 full-body previews "
        "(4 palettes × 2 LOD), **32** 512×512 PBR maps and a Blender source file.\n"
        "- **Studio import still required**: asset IDs and texture uploads not yet registered with Roblox.\n"
        "- **Total payload:** %.2f MiB. Contact sheet present.\n"
        % (sum(p.stat().st_size for p in files) / 1024**2)
    )
    (root / "validation_summary.md").write_text(output, encoding="utf-8")
    print(output)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: validate_exports.py <assets-dir>")
    main(sys.argv[1])
